window.COURSE = [{"id": "elige-tu-recorrido", "title": "Elige tu recorrido", "group": "ORIENTACIÓN", "blocks": [{"type": "p", "text": "Antes de elegir tecnologías, decide qué clase de trabajo vas a hacer. Los recorridos pueden sucederse, pero un prototipo no se convierte en producto operativo solo por publicarlo."}, {"type": "table", "rows": [["Recorrido", "Qué intentas aprender", "Condición de salida"], ["Exploración", "Si una idea merece más trabajo", "Una observación útil y una decisión"], ["MVP con usuarios", "Si un flujo resuelve una necesidad real", "Utilidad observada y riesgos controlados"], ["Producto en operación", "Si puedes sostener el servicio", "Responsable, controles y recuperación comprobada"]]}, {"type": "h", "text": "Exploración"}, {"type": "p", "text": "Usa datos ficticios y el mínimo código necesario. Un prototipo local o una demo pública sin datos privados puede servir. Marca lo simulado: una pantalla de acceso sin autenticación real no debe aparentar que protege información."}, {"type": "h", "text": "MVP con usuarios"}, {"type": "p", "text": "Acota usuarios, datos y funciones. Si hay cuentas o información privada, implementa los permisos antes de invitar personas. Define cómo recogerás feedback, atenderás errores y retirarás la prueba si deja de ser segura o útil."}, {"type": "h", "text": "Producto en operación"}, {"type": "p", "text": "Exige controles reproducibles, despliegues rastreables, monitoreo, recuperación y una persona responsable. Ajusta la profundidad según el riesgo: una página informativa y un sistema con pagos o datos sensibles no tienen las mismas necesidades."}], "number": 1, "description": "Antes de elegir tecnologías, decide qué clase de trabajo vas a hacer. Los recorridos pueden sucederse, pero un prototipo no se convierte en producto operativo solo por publicarlo."}, {"id": "entiende-a-tu-colaborador-de-ia", "title": "Entiende a tu colaborador de IA", "group": "FUNDAMENTOS", "blocks": [{"type": "p", "text": "Aquí usamos vibe coding como una puerta de entrada al desarrollo mediante instrucciones en lenguaje natural. Cuando el producto afecta a usuarios reales, añadimos prácticas de ingeniería: requisitos, control de cambios, verificación y operación."}, {"type": "h", "text": "Qué puede hacer un agente"}, {"type": "p", "text": "Según la herramienta y los permisos, puede leer un repositorio, proponer un plan, editar archivos, ejecutar comandos y comprobar resultados. Su capacidad depende del modelo, del contexto disponible, de las herramientas y de los límites del entorno."}, {"type": "h", "text": "Qué no debes dar por hecho"}, {"type": "table", "rows": [["Fallo posible", "Respuesta práctica"], ["API o paquete inexistente", "Comprobar existencia y versión en la fuente oficial"], ["Solución basada en un supuesto falso", "Separar hechos, hipótesis y dudas antes de implementar"], ["Cambios fuera de alcance", "Definir límites y revisar el diff"], ["Pruebas adaptadas al error", "Revisar cambios en tests contra los requisitos"], ["Verificación solo declarada", "Pedir comandos, resultados y comprobaciones omitidas"], ["Instrucciones maliciosas en archivos", "Tratar contenido externo como datos y limitar herramientas"]]}, {"type": "h", "text": "No confundas confianza verbal con certeza"}, {"type": "p", "text": "Que el agente diga “resuelto” describe su conclusión, no una prueba. Solicita evidencia proporcionada al cambio y examina las consecuencias. Otra IA puede ayudar a revisar, pero también compartir el mismo supuesto equivocado."}, {"type": "h", "text": "No existe un prompt que garantice el resultado"}, {"type": "p", "text": "Un buen prompt reduce ambigüedad. Los permisos restringen acciones. Las pruebas comprueban comportamientos. La revisión evalúa decisiones y riesgos. Estos mecanismos se complementan; ninguno vuelve infalible al sistema. [1, 2, 3]"}], "number": 2, "description": "Aquí usamos vibe coding como una puerta de entrada al desarrollo mediante instrucciones en lenguaje natural. Cuando el producto afecta a usuarios reales, añadimos prácticas de ingeniería: requisitos, control de cambios, verificación y operación."}, {"id": "aprende-mediante-ciclos-cortos", "title": "Aprende mediante ciclos cortos", "group": "FUNDAMENTOS", "blocks": [{"type": "p", "text": "El mapa es una orientación, no una cadena rígida. Una observación de usuario puede cambiar el alcance; una prueba técnica puede invalidar la arquitectura. Reserva espacio para volver atrás antes de invertir más trabajo."}, {"type": "img", "src": "diagrama-1.png", "alt": "Ciclo de aprendizaje con revisión de la hipótesis y verificación"}, {"type": "h", "text": "Tres bucles que conviene distinguir"}, {"type": "table", "rows": [["Bucle", "Pregunta central", "Qué revisas si falla"], ["Producto", "¿Esto resulta útil?", "Problema, usuario, propuesta y alcance"], ["Implementación", "¿Hace lo acordado?", "Código, datos, interacción y pruebas"], ["Operación", "¿Podemos sostenerlo?", "Capacidad, costos, alertas y recuperación"]]}, {"type": "h", "text": "Decisiones con evidencia"}, {"type": "p", "text": "Para cada etapa registra: qué necesitas decidir, qué evidencia respalda la decisión y qué condición impide avanzar. La cantidad de documentos puede variar; la necesidad de comprobar lo importante permanece."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El siguiente paso reduce una incertidumbre concreta."}, {"type": "p", "text": "Evidencia necesaria. Una pregunta, un experimento acotado y una observación que puedas interpretar."}, {"type": "p", "text": "Detente si: Estás construyendo más funciones para evitar comprobar si la primera sirve."}], "number": 3, "description": "El mapa es una orientación, no una cadena rígida. Una observación de usuario puede cambiar el alcance; una prueba técnica puede invalidar la arquitectura. Reserva espacio para volver atrás antes de invertir más trabajo."}, {"id": "define-y-valida-el-problema", "title": "Define y valida el problema", "group": "DESCUBRIR", "blocks": [{"type": "h", "text": "Cinco preguntas iniciales"}, {"type": "li", "text": "¿Qué dificultad concreta quieres resolver?"}, {"type": "li", "text": "¿Quién la tiene y en qué situación aparece?"}, {"type": "li", "text": "¿Cómo se resuelve hoy?"}, {"type": "li", "text": "¿Qué cambio útil debería producir tu solución?"}, {"type": "li", "text": "¿Qué queda fuera de esta primera versión?"}, {"type": "h", "text": "Ejemplo de trabajo"}, {"type": "p", "text": "StudentHub explora cómo ayudar a estudiantes a encontrar sus pendientes académicos. La hipótesis es que reunir entregas próximas y su estado reduce la confusión. No damos esa utilidad por demostrada porque podamos guardar tareas."}, {"type": "h", "text": "MVP como prueba de una hipótesis"}, {"type": "p", "text": "Primera versión posible: crear una tarea con fecha, ver pendientes próximos y marcar una tarea como completada. Los apuntes, la comunidad, los pagos y el tutor con IA pueden esperar. Si solo pruebas interacción con datos ficticios, quizá todavía no necesites cuentas."}, {"type": "table", "rows": [["Tipo de validación", "Qué demuestra", "Ejemplo"], ["Funcional", "El sistema hace una operación", "La tarea se guarda y persiste"], ["De utilidad", "La persona logra su objetivo", "Encuentra qué entregar a continuación"], ["De producto", "El uso aporta valor sostenido", "Vuelve a utilizarlo por su utilidad"]]}, {"type": "h", "text": "Investiga usuarios y viabilidad"}, {"type": "p", "text": "Observa alternativas, dificultades, lenguaje y contexto de uso. Revisa integraciones, permisos, costos y restricciones técnicas. Usa la IA para organizar evidencia y preguntas; no presentes usuarios simulados o respuestas generadas como investigación real."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "Vale la pena probar una solución acotada."}, {"type": "p", "text": "Evidencia necesaria. Observaciones reales, una hipótesis explícita y un flujo que permite evaluarla."}, {"type": "p", "text": "Detente si: Solo tienes una lista de funciones o desconoces una integración esencial."}], "number": 4, "description": "StudentHub explora cómo ayudar a estudiantes a encontrar sus pendientes académicos. La hipótesis es que reunir entregas próximas y su estado reduce la confusión. No damos esa utilidad por demostrada porque podamos guardar tareas."}, {"id": "elige-tecnologias-por-necesidad", "title": "Elige tecnologías por necesidad", "group": "PREPARAR", "blocks": [{"type": "p", "text": "La herramienta adecuada es la que permite resolver el trabajo con un nivel de control y mantenimiento que puedas asumir. Compara capacidades actuales en fuentes oficiales, no solo demos o promesas comerciales."}, {"type": "table", "rows": [["Necesidad", "Categoría que conviene evaluar"], ["Explorar una interfaz rápidamente", "Constructores visuales o entornos en navegador"], ["Trabajar en un repositorio existente", "Editor o agente que inspeccione y modifique el código"], ["Ejecutar tareas técnicas locales", "Agente de terminal con permisos delimitados"], ["Mantener un servicio", "Entorno con código exportable, pruebas y despliegues rastreables"]]}, {"type": "p", "text": "Replit, Lovable, Bolt, Cursor y Claude Code son ejemplos de herramientas para evaluar. Sus funciones, restricciones y precios cambian. Comprueba exportación, acceso al código, tratamiento de datos y control sobre el despliegue antes de depender de ellas."}, {"type": "h", "text": "Un stack posible para el ejemplo"}, {"type": "p", "text": "Next.js con TypeScript, Tailwind CSS, PostgreSQL mediante Supabase, Supabase Auth cuando se necesiten cuentas, Git y GitHub, Playwright para recorridos de navegador y un hosting compatible como Vercel. Este conjunto es una opción, no una receta obligatoria."}, {"type": "h", "text": "Antes de agregar una tecnología"}, {"type": "li", "text": "Identifica la necesidad concreta que cubre."}, {"type": "li", "text": "Comprueba documentación, compatibilidad y mantenimiento."}, {"type": "li", "text": "Evalúa costos, exportación y dependencia del proveedor."}, {"type": "li", "text": "Prefiere capacidades existentes cuando sean suficientes."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El stack es adecuado y comprensible para el equipo."}, {"type": "p", "text": "Evidencia necesaria. Una razón por elección y una prueba de las integraciones inciertas."}, {"type": "p", "text": "Detente si: La elección depende de una API no verificada o agrega complejidad sin utilidad clara."}], "number": 5, "description": "La herramienta adecuada es la que permite resolver el trabajo con un nivel de control y mantenimiento que puedas asumir. Compara capacidades actuales en fuentes oficiales, no solo demos o promesas comerciales."}, {"id": "prepara-un-entorno-reproducible", "title": "Prepara un entorno reproducible", "group": "PREPARAR", "blocks": [{"type": "p", "text": "Para un proyecto web local necesitas un editor o agente, Git, un runtime compatible, un gestor de paquetes y un navegador. Docker, clientes de API y otras utilidades se agregan cuando el proyecto las requiera."}, {"type": "h", "text": "Comprueba las herramientas"}, {"type": "code", "text": "node --version\nnpm --version\ngit --version"}, {"type": "p", "text": "Registra la versión de Node usada y el gestor elegido. Conserva el archivo de bloqueo de dependencias. Evita mezclar gestores sin una decisión explícita."}, {"type": "h", "text": "Inicia el repositorio"}, {"type": "code", "text": "mkdir student-dashboard\ncd student-dashboard\ngit init"}, {"type": "p", "text": "Estos comandos no generan la aplicación. Sigue el procedimiento oficial de inicialización del framework elegido y revisa las opciones antes de ejecutar comandos sugeridos. Después configura el repositorio remoto."}, {"type": "h", "text": "Comprueba que se pueda reconstruir"}, {"type": "p", "text": "Desde un checkout limpio, otra persona o la CI debe poder instalar las dependencias, configurar un entorno de prueba y ejecutar las comprobaciones documentadas. Para npm, npm ci requiere un lockfile compatible y puede usarse en ese recorrido."}, {"type": "code", "text": "npm ci\nnpm run lint\nnpm run typecheck\nnpm test\nnpm run build"}, {"type": "p", "text": "Los scripts son ejemplos: deben existir en package.json. No inventes un resultado satisfactorio cuando una comprobación no está configurada. Registra qué falta y decide si impide avanzar."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El proyecto se instala y verifica fuera de tu sesión habitual."}, {"type": "p", "text": "Evidencia necesaria. Versiones registradas, lockfile y ejecución limpia de los comandos disponibles."}, {"type": "p", "text": "Detente si: Solo funciona gracias a archivos, credenciales o pasos locales sin documentar."}], "number": 6, "description": "Para un proyecto web local necesitas un editor o agente, Git, un runtime compatible, un gestor de paquetes y un navegador. Docker, clientes de API y otras utilidades se agregan cuando el proyecto las requiera."}, {"id": "organiza-el-contexto-con-criterio", "title": "Organiza el contexto con criterio", "group": "PREPARAR", "blocks": [{"type": "p", "text": "El objetivo es aportar información relevante y vigente, no maximizar archivos o tokens. Empieza con una entrada breve y carga los detalles cuando la tarea los necesite. [1]"}, {"type": "table", "rows": [["Documento", "Contenido", "Cuándo resulta útil"], ["README.md", "Instalación, comandos y mapa del proyecto", "Siempre"], ["PRD.md", "Problema, hipótesis, alcance y aceptación", "Al definir el producto"], ["Instrucciones del agente", "Reglas, límites y referencias", "Al trabajar con IA"], ["TASKS.md", "Tareas y criterios de finalización", "Durante la implementación"], ["ARCHITECTURE.md", "Límites y responsabilidades", "Cuando hay decisiones técnicas relevantes"], ["DESIGN.md", "Interacción y sistema visual", "Cuando se necesita consistencia"], ["DECISIONS.md", "Decisión, motivo y consecuencias", "Para elecciones importantes"], ["TEST_PLAN.md y SECURITY.md", "Comprobaciones y riesgos", "Al introducir comportamientos o datos críticos"], ["MEMORY.md", "Estado breve y pendientes", "Para retomar sesiones largas"]]}, {"type": "h", "text": "Carga selectiva"}, {"type": "p", "text": "Una tarea visual necesita referencias de interfaz y componentes. Un cambio de permisos necesita el modelo de acceso y sus pruebas. El agente puede consultar más archivos si identifica una dependencia; no debe asumir que lo no leído carece de importancia."}, {"type": "h", "text": "Memoria verificable y fuentes de verdad"}, {"type": "p", "text": "Incluye fecha o revisión de referencia, tarea actual, resultados comprobados y asuntos pendientes. Contrasta el resumen con código, pruebas y decisiones vigentes. Si se contradicen, resuelve la diferencia antes de programar. La memoria no es una garantía de lo sucedido."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El agente puede localizar el contexto necesario."}, {"type": "p", "text": "Evidencia necesaria. Una entrada breve, referencias claras y estado contrastado."}, {"type": "p", "text": "Detente si: Hay instrucciones contradictorias o documentos que describen un producto inexistente."}], "number": 7, "description": "El objetivo es aportar información relevante y vigente, no maximizar archivos o tokens. Empieza con una entrada breve y carga los detalles cuando la tarea los necesite. [1]"}, {"id": "escribe-requisitos-verificables", "title": "Escribe requisitos verificables", "group": "PREPARAR", "blocks": [{"type": "p", "text": "El PRD explica qué quieres conseguir y por qué. Mantén separados el problema, la hipótesis de utilidad y los comportamientos que la implementación debe cumplir."}, {"type": "code", "text": "# PRD — StudentHub\n \n## Problema observado\nLos estudiantes consultados tienen dificultades para identificar\nqué entrega deben atender a continuación.\n \n## Hipótesis\nUna lista ordenada de pendientes puede reducir esa dificultad.\n \n## Usuario y contexto\nEstudiantes que gestionan entregas de varias asignaturas.\n \n## Primera versión\n- Crear tarea con título y fecha\n- Ver pendientes próximos\n- Marcar tarea como completada\n \n## Fuera de alcance\nPagos, tutor con IA, comunidad y aplicación móvil nativa.\n \n## Aceptación funcional\nLa tarea válida se guarda y permanece después de recargar.\nLas entradas inválidas muestran un mensaje comprensible.\nSi hay cuentas, cada persona accede solo a sus tareas.\n \n## Validación de utilidad\nObservar si las personas identifican su siguiente entrega\nsin ayuda y qué obstáculos encuentran.\n \n## Incertidumbres\nConfirmar cómo quieren ordenar entregas con la misma fecha."}, {"type": "p", "text": "Este es un ejemplo de estructura: sustituye las afirmaciones sobre usuarios por evidencia real. Define antes de la prueba qué observarás y cómo interpretarás los resultados. No inventes porcentajes de éxito ni resultados de investigación."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El equipo entiende qué construir y cómo evaluarlo."}, {"type": "p", "text": "Evidencia necesaria. Alcance explícito, criterios comprobables y plan de validación."}, {"type": "p", "text": "Detente si: La única medida de éxito es terminar pantallas o generar código."}], "number": 8, "description": "El PRD explica qué quieres conseguir y por qué. Mantén separados el problema, la hipótesis de utilidad y los comportamientos que la implementación debe cumplir."}, {"id": "disena-responsabilidades-y-datos", "title": "Diseña responsabilidades y datos", "group": "DISEÑAR", "blocks": [{"type": "p", "text": "La arquitectura explica los límites del sistema. Antes de multiplicar carpetas, identifica qué código llega al navegador, qué operaciones requieren servidor y dónde se aplican permisos."}, {"type": "img", "src": "diagrama-2.png", "alt": "Arquitectura desde la interfaz hasta los servicios y los datos"}, {"type": "p", "text": "El diagrama muestra una opción con servidor y capa de servicios. Otras arquitecturas pueden permitir acceso del cliente a datos mediante políticas de acceso. Elige una y documenta sus límites de confianza; no mezcles modelos por accidente."}, {"type": "h", "text": "Modelo mínimo del ejemplo"}, {"type": "table", "rows": [["Entidad o regla", "Definición posible"], ["Tarea", "id, título, fecha, estado y propietario si hay cuentas"], ["Propiedad", "El propietario se obtiene de la identidad validada"], ["Acceso", "Lectura y modificación limitadas al usuario autorizado"], ["Tiempo", "Definir fecha, zona horaria y criterio de orden"], ["Integridad", "Campos requeridos y valores válidos"]]}, {"type": "h", "text": "Estructura proporcional"}, {"type": "p", "text": "Usa app/, components/, features/ y otras carpetas si clarifican responsabilidades. No crees services/, lib/, types/ y utils/ vacíos por cumplir una plantilla. Evita duplicar lógica o dispersar una función sin una razón práctica."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "Puedes explicar el recorrido y la protección de los datos."}, {"type": "p", "text": "Evidencia necesaria. Modelo, límites y una decisión técnica breve."}, {"type": "p", "text": "Detente si: El navegador puede enviar un propietario arbitrario o los permisos dependen de ocultar botones."}], "number": 9, "description": "La arquitectura explica los límites del sistema. Antes de multiplicar carpetas, identifica qué código llega al navegador, qué operaciones requieren servidor y dónde se aplican permisos."}, {"id": "disena-uso-y-estados-completos", "title": "Diseña uso y estados completos", "group": "DISEÑAR", "blocks": [{"type": "p", "text": "Un sistema visual útil define también cómo interactúa la persona, qué información necesita y cómo se recupera de errores. Comienza por el flujo principal antes de ampliar la biblioteca de componentes."}, {"type": "table", "rows": [["Aspecto", "Qué definir"], ["Jerarquía", "Qué es principal, secundario y contextual"], ["Tipografía y color", "Legibilidad, escalas y contraste en su uso real"], ["Componentes", "Variantes, estados y comportamiento"], ["Formulario", "Etiquetas, validación y mensajes útiles"], ["Responsive", "Reordenamiento y contenido según espacio"], ["Accesibilidad", "Teclado, foco visible y nombres comprensibles"]]}, {"type": "h", "text": "Todos los estados forman parte del producto"}, {"type": "li", "text": "Carga: mostrar progreso sin permitir acciones duplicadas."}, {"type": "li", "text": "Vacío: explicar cómo empezar."}, {"type": "li", "text": "Error: comunicar qué ocurrió y cómo continuar."}, {"type": "li", "text": "Éxito: confirmar el resultado sin depender solo del color."}, {"type": "li", "text": "Sesión caducada: recuperar el acceso sin perder información innecesariamente."}, {"type": "h", "text": "Ejemplo de DESIGN.md"}, {"type": "code", "text": "Estilo: claro, sobrio y orientado a tareas.\nTipografía: una familia legible con escala consistente.\nComponentes: reutilizar los existentes.\nAcción principal: crear una tarea.\nAcción destructiva: confirmar cuando corresponda al riesgo.\nEstados: carga, vacío, error y éxito.\nRevisión: teclado, móvil y contenido real."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El flujo se entiende y se puede recorrer."}, {"type": "p", "text": "Evidencia necesaria. Prueba con contenido representativo, teclado y pantallas relevantes."}, {"type": "p", "text": "Detente si: La interfaz solo funciona con datos ideales o no explica cómo recuperarse de un error."}], "number": 10, "description": "Un sistema visual útil define también cómo interactúa la persona, qué información necesita y cómo se recupera de errores. Comienza por el flujo principal antes de ampliar la biblioteca de componentes."}, {"id": "limita-acciones-y-conserva-decisiones", "title": "Limita acciones y conserva decisiones", "group": "DISEÑAR", "blocks": [{"type": "h", "text": "Tres mecanismos distintos"}, {"type": "table", "rows": [["Mecanismo", "Ejemplo", "Qué aporta"], ["Instrucción", "No cambiar el esquema sin autorización", "Orienta al agente"], ["Restricción", "Credenciales limitadas y aislamiento", "Acota lo que puede hacer"], ["Evidencia", "Diff y comprobación de permisos", "Permite evaluar lo realizado"]]}, {"type": "p", "text": "No sustituyas una restricción técnica por una frase en RULES.md. Para un agente que ejecuta comandos, evalúa permisos de archivos, red e integraciones. Usa acceso mínimo y evita credenciales de producción en el entorno de desarrollo. [2]"}, {"type": "h", "text": "Reglas de trabajo breves"}, {"type": "li", "text": "Inspecciona lo existente y conserva los cambios ajenos."}, {"type": "li", "text": "No cambies el alcance ni agregues dependencias sin justificarlo."}, {"type": "li", "text": "No ejecutes operaciones destructivas ni publiques por inferencia."}, {"type": "li", "text": "Comprueba las APIs y versiones que no conozcas."}, {"type": "li", "text": "No ocultes fallos desactivando pruebas o controles."}, {"type": "li", "text": "Informa resultados, limitaciones y asuntos pendientes."}, {"type": "p", "text": "Usa el archivo de instrucciones que tu herramienta reconozca y enlaza documentación adicional. RULES.md por sí solo no se carga en todos los editores. Confirma el comportamiento en la documentación de la herramienta."}, {"type": "h", "text": "Registra decisiones importantes"}, {"type": "code", "text": "ADR-001\nDecisión: usar un servicio de autenticación mantenido.\nMotivo: el equipo no desarrollará su propio sistema de claves.\nAlternativas consideradas: ...\nConsecuencias: dependencia del proveedor y configuración de acceso.\nRevisar si: cambian los requisitos de identidad o exportación."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "Las acciones permitidas están delimitadas."}, {"type": "p", "text": "Evidencia necesaria. Reglas comprensibles y permisos técnicos acordes al trabajo."}, {"type": "p", "text": "Detente si: El agente tiene acceso innecesario a datos o puede publicar cambios críticos sin revisión."}], "number": 11, "description": "No sustituyas una restricción técnica por una frase en RULES.md. Para un agente que ejecuta comandos, evalúa permisos de archivos, red e integraciones. Usa acceso mínimo y evita credenciales de producción en el entorno de desarrollo. [2]"}, {"id": "construye-una-unidad-verificable", "title": "Construye una unidad verificable", "group": "IMPLEMENTAR", "blocks": [{"type": "p", "text": "El tamaño correcto de una tarea depende del comportamiento y el riesgo. Una función completa puede ser más coherente que dividir artificialmente cada campo, archivo y test en conversaciones separadas."}, {"type": "h", "text": "Corte vertical del ejemplo"}, {"type": "p", "text": "Crear tarea → validar → guardar con permisos → recuperar → mostrar → recargar y comprobar persistencia. Este recorrido conecta interfaz, lógica y datos para descubrir fallos de integración pronto."}, {"type": "h", "text": "Plantilla de tarea"}, {"type": "code", "text": "TASK-012 — Crear una tarea\n \nObjetivo: registrar una entrega con título y fecha.\nAlcance: formulario, operación de guardado y lista actualizada.\nFuera de alcance: recordatorios, pagos y tareas compartidas.\nDependencias: modelo y permisos definidos.\n \nAceptación:\n- Datos válidos se guardan y persisten al recargar.\n- Datos inválidos no generan registros.\n- La persona recibe un mensaje útil si falla el guardado.\n- Si hay cuentas, no se puede crear para otro propietario.\n \nEvidencia:\n- Pruebas del comportamiento\n- Recorrido manual o E2E\n- Diff revisado y limitaciones informadas"}, {"type": "h", "text": "Cuándo dividir más"}, {"type": "p", "text": "Divide si la tarea acumula decisiones independientes, afecta varias áreas críticas o no se puede revisar con claridad. Durante el aprendizaje puede convenir implementar primero una interfaz con datos ficticios; después completa la integración sin perder el objetivo del flujo."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "La unidad está terminada y revisada."}, {"type": "p", "text": "Evidencia necesaria. Criterios satisfechos y comprobaciones registradas."}, {"type": "p", "text": "Detente si: La tarea solo parece completa porque se ocultaron errores o se dejó pendiente la protección de datos."}], "number": 12, "description": "El tamaño correcto de una tarea depende del comportamiento y el riesgo. Una función completa puede ser más coherente que dividir artificialmente cada campo, archivo y test en conversaciones separadas."}, {"id": "da-contexto-y-pide-evidencia", "title": "Da contexto y pide evidencia", "group": "IMPLEMENTAR", "blocks": [{"type": "h", "text": "Prompt antes de modificar"}, {"type": "code", "text": "Lee README.md y las instrucciones del agente.\nConsulta los requisitos y documentos pertinentes a TASK-012.\nInspecciona la implementación existente.\n \nTodavía no modifiques archivos.\nResume el comportamiento esperado, los límites del cambio\ny las dudas que afecten a la solución.\nPropón un plan proporcional al riesgo y cómo comprobarlo."}, {"type": "h", "text": "Prompt de implementación"}, {"type": "code", "text": "CONTEXTO\nStudentHub necesita registrar tareas con fecha.\n \nTAREA\nImplementa TASK-012 según sus criterios de aceptación.\n \nARCHIVOS\nLocaliza los módulos relevantes; conserva el trabajo existente.\n \nRESTRICCIONES\nReutiliza componentes y la capa de datos acordada.\nNo amplíes el alcance ni debilites pruebas o permisos.\nNo hagas push ni despliegues salvo autorización explícita.\n \nVERIFICACIÓN\nEjecuta las comprobaciones pertinentes ya configuradas.\nSi falta alguna, explica su efecto sobre la validación.\n \nENTREGA\nInforma qué cambió y por qué, archivos modificados, comandos,\nresultados observados, limitaciones y asuntos sin comprobar."}, {"type": "h", "text": "Usa las pausas donde ayuden"}, {"type": "p", "text": "Un cambio trivial y reversible puede ejecutarse directamente dentro del alcance autorizado. Un cambio de datos, permisos o arquitectura merece revisar el plan. Evita convertir cada acción pequeña en una aprobación sin contenido."}], "number": 13, "description": "Un cambio trivial y reversible puede ejecutarse directamente dentro del alcance autorizado. Un cambio de datos, permisos o arquitectura merece revisar el plan. Evita convertir cada acción pequeña en una aprobación sin contenido."}, {"id": "prueba-comportamientos-y-limites", "title": "Prueba comportamientos y límites", "group": "VERIFICAR", "blocks": [{"type": "p", "text": "Las pruebas deben derivarse del comportamiento esperado. Si el agente escribe implementación y tests, revisa que ambos no estén confirmando el mismo supuesto equivocado."}, {"type": "table", "rows": [["Nivel", "Uso útil", "Ejemplo"], ["Estático", "Detectar errores sin ejecutar el flujo", "Tipos y lint"], ["Unitario", "Comprobar una regla aislada", "Orden de fechas"], ["Integración", "Comprobar relaciones entre partes", "Guardar con permisos"], ["E2E", "Recorrer una acción desde el navegador", "Crear y recuperar una tarea"], ["Manual con usuarios", "Observar comprensión y utilidad", "Identificar la siguiente entrega"]]}, {"type": "h", "text": "Incluye casos adversos"}, {"type": "li", "text": "Solicitud sin sesión o con sesión vencida."}, {"type": "li", "text": "Intento de leer o modificar el recurso de otra persona."}, {"type": "li", "text": "Campos vacíos, valores inválidos y entradas inesperadas."}, {"type": "li", "text": "Fallo de red o del servicio de datos."}, {"type": "li", "text": "Doble envío y recarga de la página."}, {"type": "h", "text": "No pruebes todo al mismo nivel"}, {"type": "p", "text": "Prioriza recorridos y reglas de mayor riesgo. No agregues tests que solo repitan la estructura del código. Tampoco uses cobertura numérica como sustituto de comprobar permisos y comportamientos importantes."}, {"type": "h", "text": "Evidencia de ejecución"}, {"type": "p", "text": "Registra comandos, entorno, resumen de resultados y fallos pendientes. Un test no ejecutado debe figurar como no ejecutado. Los logs pueden requerir ocultar datos sensibles antes de compartirlos."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "La evidencia respalda el comportamiento acordado."}, {"type": "p", "text": "Evidencia necesaria. Pruebas relevantes y casos negativos revisados."}, {"type": "p", "text": "Detente si: Se cambiaron expectativas para aceptar el fallo o faltan comprobaciones críticas."}], "number": 14, "description": "Las pruebas deben derivarse del comportamiento esperado. Si el agente escribe implementación y tests, revisa que ambos no estén confirmando el mismo supuesto equivocado."}, {"id": "revisa-cambios-y-usa-git", "title": "Revisa cambios y usa Git", "group": "VERIFICAR", "blocks": [{"type": "p", "text": "La revisión con IA es una ayuda adicional. La persona responsable conserva el juicio sobre requisitos, riesgos y publicación. Una segunda IA tampoco garantiza independencia de criterio. [3]"}, {"type": "h", "text": "Qué revisar en el diff"}, {"type": "li", "text": "Relación entre cada cambio y la tarea acordada."}, {"type": "li", "text": "Permisos, manejo de errores y consecuencias sobre datos."}, {"type": "li", "text": "Pruebas nuevas y modificaciones en expectativas existentes."}, {"type": "li", "text": "Dependencias agregadas y código duplicado."}, {"type": "li", "text": "Cambios ajenos, secretos o desactivación de controles."}, {"type": "h", "text": "Conserva versiones comprensibles"}, {"type": "code", "text": "git status\ngit diff\ngit add src/features/tasks/ tests/\ngit diff --staged\ngit commit -m \"feat: add task creation\""}, {"type": "p", "text": "Las rutas son ejemplos: selecciona las que correspondan. Revisa el contenido preparado y respeta la autorización de commits y push. Usa ramas para aislar cambios importantes y un proceso de revisión antes de integrarlos."}, {"type": "h", "text": "Qué recupera Git"}, {"type": "p", "text": "Git permite recuperar versiones de archivos registrados. No restaura por sí mismo registros borrados de una base de datos, archivos externos ni configuración de servicios. El plan de recuperación debe contemplar cada recurso afectado."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El cambio está listo para integrarse."}, {"type": "p", "text": "Evidencia necesaria. Diff comprendido, controles relevantes satisfactorios y decisiones pendientes resueltas."}, {"type": "p", "text": "Detente si: La única revisión es la afirmación del mismo agente que implementó el cambio."}], "number": 15, "description": "La revisión con IA es una ayuda adicional. La persona responsable conserva el juicio sobre requisitos, riesgos y publicación. Una segunda IA tampoco garantiza independencia de criterio. [3]"}, {"id": "protege-a-usuarios-y-al-agente", "title": "Protege a usuarios y al agente", "group": "VERIFICAR", "blocks": [{"type": "h", "text": "Seguridad de la aplicación"}, {"type": "p", "text": "Autenticación responde quién es la persona; autorización, qué puede hacer. Verifica las dos en cada operación protegida. Una pantalla oculta o una ruta visualmente bloqueada no sustituyen permisos sobre los datos."}, {"type": "table", "rows": [["Riesgo", "Control y comprobación"], ["Acceso a datos ajenos", "Permisos en la operación y pruebas con dos usuarios"], ["Entradas inesperadas", "Validación y manejo seguro en límites de confianza"], ["Abuso del servicio", "Límites proporcionales, alertas y control de consumo"], ["Carga de archivos", "Validación de tipo, tamaño y acceso cuando exista"], ["Exposición de información", "Datos mínimos y logs sin credenciales ni contenido sensible"]]}, {"type": "h", "text": "Seguridad del entorno de IA"}, {"type": "p", "text": "Revisa herramientas, plugins y conexiones antes de conceder acceso. Limita archivos, red y credenciales a lo que necesita la tarea. Contenido de un README, una página o una salida de herramienta puede contener instrucciones maliciosas; no lo conviertas en autorización. El aislamiento reduce el alcance de un error o ataque, sin eliminar todo riesgo. [2]"}, {"type": "h", "text": "Dependencias y ejecución"}, {"type": "p", "text": "Comprueba nombre, procedencia y mantenimiento de paquetes antes de instalarlos. Revisa alertas de vulnerabilidades y evita ejecutar scripts desconocidos por una sugerencia sin verificar. Considera qué código puede ejecutarse durante instalación, pruebas y despliegue."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "Los límites de acceso están comprobados."}, {"type": "p", "text": "Evidencia necesaria. Pruebas de autorización y permisos mínimos del agente y los servicios."}, {"type": "p", "text": "Detente si: Hay una ruta de acceso sin verificar o credenciales privilegiadas innecesarias."}], "number": 16, "description": "Autenticación responde quién es la persona; autorización, qué puede hacer. Verifica las dos en cada operación protegida. Una pantalla oculta o una ruta visualmente bloqueada no sustituyen permisos sobre los datos."}, {"id": "automatiza-comprobaciones-repetibles", "title": "Automatiza comprobaciones repetibles", "group": "PREPARAR LA PUBLICACIÓN", "blocks": [{"type": "p", "text": "La integración continua o CI ejecuta controles en un entorno definido. Ayuda a detectar fallos sin depender del recuerdo de ejecutar comandos en tu computadora. GitHub Actions permite automatizar comprobaciones sobre pull requests y otros eventos. [5]"}, {"type": "h", "text": "Pipeline mínimo para el ejemplo"}, {"type": "table", "rows": [["Paso", "Qué comprueba"], ["Instalar desde el lockfile", "Dependencias del estado versionado"], ["Lint y tipos", "Errores estáticos según la configuración"], ["Pruebas pertinentes", "Reglas e integración del sistema"], ["Build", "Compilación de la versión que se publicará"], ["Preview y pruebas de humo", "Recorrido esencial en el entorno desplegado"]]}, {"type": "h", "text": "Haz que los controles importen"}, {"type": "p", "text": "Configura las comprobaciones requeridas en el proceso de integración. Un workflow que falla pero se ignora no bloquea una publicación defectuosa. No agregues secretos de producción a trabajos que no los necesiten ni a contextos de código no confiable."}, {"type": "h", "text": "Entorno y credenciales"}, {"type": "code", "text": "# Ejemplo de configuración pública para Next.js y Supabase\nNEXT_PUBLIC_SUPABASE_URL=\nNEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=\n \n# Solo si el servidor necesita operaciones privilegiadas\nSUPABASE_SECRET_KEY="}, {"type": "p", "text": "Guarda una plantilla sin valores reales en .env.example. Excluye los archivos locales con secretos mediante .gitignore y configura los valores por entorno en el hosting."}, {"type": "p", "text": "La clave publishable está destinada al cliente y necesita políticas de acceso adecuadas. La clave secret es privilegiada y no debe enviarse al navegador ni registrarse en Git. No es necesaria en todo proyecto. Los nombres y prefijos dependen del framework. [4]"}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El cambio puede verificarse automáticamente."}, {"type": "p", "text": "Evidencia necesaria. Ejecución rastreable de la CI sobre la revisión propuesta."}, {"type": "p", "text": "Detente si: Los controles críticos se omiten o las credenciales no corresponden al entorno."}], "number": 17, "description": "La integración continua o CI ejecuta controles en un entorno definido. Ayuda a detectar fallos sin depender del recuerdo de ejecutar comandos en tu computadora. GitHub Actions permite automatizar comprobaciones sobre pull requests y otros eventos. [5]"}, {"id": "versiona-datos-y-prepara-recuperacion", "title": "Versiona datos y prepara recuperación", "group": "PREPARAR LA PUBLICACIÓN", "blocks": [{"type": "p", "text": "Una migración registra un cambio del esquema de datos. Conserva esas instrucciones en el repositorio y prueba su aplicación sobre un entorno de ensayo. Evita cambios manuales que nadie pueda reconstruir. [6]"}, {"type": "h", "text": "Antes de modificar la base de datos"}, {"type": "li", "text": "Identifica el impacto sobre registros existentes."}, {"type": "li", "text": "Comprueba duración, bloqueos y compatibilidad de versiones."}, {"type": "li", "text": "Ensaya la migración con datos representativos y protegidos."}, {"type": "li", "text": "Define qué harás si falla a mitad del proceso."}, {"type": "li", "text": "Verifica una copia de seguridad apropiada al cambio."}, {"type": "h", "text": "Separa recuperación de código y datos"}, {"type": "table", "rows": [["Recurso", "Mecanismo posible", "Evidencia"], ["Código", "Volver a una versión validada", "Versión identificada y recorrido comprobado"], ["Base de datos", "Restaurar backup o corregir mediante migración", "Ensayo de recuperación y comprobación de integridad"], ["Archivos externos", "Backup y restauración del almacenamiento", "Archivos recuperados con permisos correctos"], ["Configuración", "Inventario protegido por entorno", "Valores necesarios identificados sin exponer secretos"]]}, {"type": "p", "text": "Restaurar datos puede perder cambios posteriores al backup. Define cuánta pérdida es tolerable y cuánto tiempo puede estar interrumpido el servicio. No reviertas credenciales comprometidas a un valor viejo: rótalas y revoca lo expuesto."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "Existe una salida practicable si el cambio falla."}, {"type": "p", "text": "Evidencia necesaria. Migración ensayada, copia recuperable y responsable de recuperación."}, {"type": "p", "text": "Detente si: Solo sabes volver al commit anterior o nunca has comprobado la restauración."}], "number": 18, "description": "Una migración registra un cambio del esquema de datos. Conserva esas instrucciones en el repositorio y prueba su aplicación sobre un entorno de ensayo. Evita cambios manuales que nadie pueda reconstruir. [6]"}, {"id": "publica-una-version-identificable", "title": "Publica una versión identificable", "group": "DESPLEGAR", "blocks": [{"type": "p", "text": "Local → preview → QA → producción es una ruta común. En cada paso conserva la relación entre código, configuración y cambios de datos. Una URL accesible no demuestra que el despliegue esté listo."}, {"type": "h", "text": "Aísla los entornos"}, {"type": "table", "rows": [["Entorno", "Datos y uso"], ["Desarrollo", "Datos ficticios o de prueba"], ["Preview", "Ensayo sin acceso accidental a datos reales"], ["Producción", "Usuarios reales y permisos operativos controlados"]]}, {"type": "h", "text": "Verifica la preview"}, {"type": "p", "text": "Prueba el recorrido principal, errores, permisos, enlaces directos, recarga, móvil y teclado. Comprueba variables, redirecciones de autenticación y conexiones a datos. Verifica que cada dependencia apunta al entorno correcto."}, {"type": "h", "text": "Registro breve de publicación"}, {"type": "code", "text": "Versión o commit: ...\nEntorno y configuración verificados: ...\nMigraciones necesarias: ...\nComprobaciones y resultados: ...\nProblemas conocidos aceptados: ...\nResponsable de publicación y recuperación: ...\nPlan si falla: ..."}, {"type": "h", "text": "Después de publicar"}, {"type": "p", "text": "Ejecuta pruebas de humo sobre la URL real sin dañar datos de usuarios. Observa errores y rendimiento. Si la versión falla, evalúa si basta recuperar código o si también hay que corregir datos o configuración."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "La versión puede recibir el uso previsto."}, {"type": "p", "text": "Evidencia necesaria. Preview validada, versión rastreable, responsable y plan de recuperación."}, {"type": "p", "text": "Detente si: Hay controles críticos fallidos o no sabes qué revisión y qué datos estás publicando."}], "number": 19, "description": "Local → preview → QA → producción es una ruta común. En cada paso conserva la relación entre código, configuración y cambios de datos. Una URL accesible no demuestra que el despliegue esté listo."}, {"id": "opera-y-aprende-del-uso-real", "title": "Opera y aprende del uso real", "group": "MANTENER", "blocks": [{"type": "p", "text": "Operar significa detectar problemas, responder a ellos y sostener el servicio. No se resuelve instalando un panel de analítica: define qué señales importan y quién actuará."}, {"type": "table", "rows": [["Señal", "Pregunta que ayuda a responder"], ["Errores", "¿Qué flujo está fallando y desde cuándo?"], ["Disponibilidad", "¿La aplicación responde?"], ["Rendimiento", "¿La experiencia se degrada?"], ["Datos y backups", "¿Podemos recuperar información?"], ["Consumo y costos", "¿Estamos dentro del presupuesto?"], ["Feedback y uso", "¿El producto sigue siendo útil?"]]}, {"type": "h", "text": "Presupuesto y alertas"}, {"type": "p", "text": "Identifica costos fijos y variables: hosting, base de datos, almacenamiento, correo y APIs. Configura alertas y límites cuando el proveedor los permita. Una alerta de gasto no siempre detiene el consumo: comprueba su comportamiento."}, {"type": "h", "text": "Respuesta básica a incidentes"}, {"type": "p", "text": "Detectar → dimensionar impacto → contener → recuperar → verificar → comunicar lo necesario → registrar aprendizaje. Si hay exposición de credenciales, revócalas o rótalas; borrar el archivo no neutraliza una clave filtrada."}, {"type": "h", "text": "Mantenimiento y documentación"}, {"type": "p", "text": "Revisa dependencias, alertas y políticas de acceso con una frecuencia acorde al riesgo. Actualiza README, decisiones, tareas y contexto cuando cambie el sistema. Revisa también si el producto merece seguir creciendo, mantenerse o retirarse."}, {"type": "h", "text": "Decisión para avanzar"}, {"type": "p", "text": "El servicio tiene una operación sostenible."}, {"type": "p", "text": "Evidencia necesaria. Responsable, alertas accionables, recuperación ensayada y presupuesto conocido."}, {"type": "p", "text": "Detente si: Nadie recibe alertas o una caída depende de que un usuario la denuncie por casualidad."}], "number": 20, "description": "Operar significa detectar problemas, responder a ellos y sostener el servicio. No se resuelve instalando un panel de analítica: define qué señales importan y quién actuará."}, {"id": "depura-sin-ampliar-el-problema", "title": "Depura sin ampliar el problema", "group": "RESOLVER Y RETOMAR", "blocks": [{"type": "h", "text": "Describe el fallo de forma reproducible"}, {"type": "code", "text": "ERROR\nMensaje y contexto, sin secretos.\n \nESPERADO\nLa tarea debería guardarse y aparecer en la lista.\n \nOBSERVADO\nLa interfaz confirma el guardado, pero al recargar desaparece.\n \nREPRODUCCIÓN\n1. Iniciar sesión con una cuenta de prueba.\n2. Crear una tarea válida.\n3. Recargar y revisar el resultado.\n \nRESTRICCIONES\nNo cambies el esquema ni los permisos sin justificarlo.\n \nPRIMER PASO\nNo modifiques código todavía. Identifica hipótesis, evidencia\ny la comprobación más pequeña para distinguir la causa."}, {"type": "h", "text": "Corrige después del diagnóstico"}, {"type": "p", "text": "Pide la corrección mínima coherente con la causa y una prueba que reproduzca el fallo. Si se necesita cambiar el alcance o la arquitectura, hazlo explícito. Evita encadenar arreglos especulativos o desactivar controles para obtener un resultado en verde."}, {"type": "h", "text": "Retoma una sesión con contexto breve"}, {"type": "code", "text": "Estado comprobado: ...\nRevisión de código o versión: ...\nTarea actual y alcance: ...\nÚltimas pruebas y resultados: ...\nHipótesis pendientes: ...\nSiguiente comprobación: ..."}, {"type": "p", "text": "El código, las decisiones y la ejecución real deben respaldar este resumen. Cuando haya contradicciones, investiga antes de confiar en la memoria del agente."}], "number": 21, "description": "Pide la corrección mínima coherente con la causa y una prueba que reproduzca el fallo. Si se necesita cambiar el alcance o la arquitectura, hazlo explícito. Evita encadenar arreglos especulativos o desactivar controles para obtener un resultado en verde."}, {"id": "comprueba-antes-de-avanzar", "title": "Comprueba antes de avanzar", "group": "REFERENCIA PRÁCTICA", "blocks": [{"type": "table", "rows": [["Recorrido", "Evidencia mínima para pasar a otro nivel"], ["Exploración", "Problema e hipótesis explícitos; datos ficticios; observación de utilidad; límites del prototipo visibles"], ["MVP con usuarios", "Flujo útil; aceptación funcional; permisos probados si hay cuentas; configuración separada; responsable y vía de feedback"], ["Producto en operación", "Controles automáticos; versión rastreable; migraciones ensayadas; recuperación comprobada; alertas, presupuesto y responsable"]]}, {"type": "h", "text": "Por cada función"}, {"type": "li", "text": "Entender el comportamiento y las restricciones."}, {"type": "li", "text": "Consultar el contexto pertinente y lo ya implementado."}, {"type": "li", "text": "Planificar según la incertidumbre y el riesgo."}, {"type": "li", "text": "Implementar una unidad revisable."}, {"type": "li", "text": "Probar comportamientos y casos negativos relevantes."}, {"type": "li", "text": "Revisar el diff y la evidencia de ejecución."}, {"type": "li", "text": "Registrar una versión según la política del proyecto."}, {"type": "li", "text": "Actualizar el contexto que realmente cambió."}, {"type": "h", "text": "Señales para detenerse"}, {"type": "p", "text": "Permisos sin comprobar, secretos expuestos, datos de producción en una prueba accidental, controles críticos desactivados, migraciones no ensayadas o afirmaciones de calidad sin evidencia. Resuelve la causa antes de continuar."}, {"type": "h", "text": "Glosario breve"}, {"type": "p", "text": "MVP: primera versión para validar utilidad. Stack: tecnologías del proyecto. PRD: requisitos del producto. ADR: registro de una decisión técnica. Diff: diferencias entre versiones. CI: integración continua. E2E: recorrido de extremo a extremo. Preview: despliegue previo. QA: verificación de calidad. RLS: políticas de acceso por fila. Rollback: recuperación de una versión anterior, cuyo alcance depende del recurso."}, {"type": "p", "text": "El criterio final no es cuánto código produjo la IA. Es qué problema resolviste, qué comprobaste y qué puedes sostener con responsabilidad."}], "number": 22, "description": "Permisos sin comprobar, secretos expuestos, datos de producción en una prueba accidental, controles críticos desactivados, migraciones no ensayadas o afirmaciones de calidad sin evidencia. Resuelve la causa antes de continuar."}, {"id": "fuentes-y-alcance-de-la-guia", "title": "Fuentes y alcance de la guía", "group": "CONSULTA", "blocks": [{"type": "p", "text": "Esta edición reorganiza y amplía el material inicial con criterios editoriales de desarrollo de producto e ingeniería. Las plantillas son ejemplos adaptables. Las fuentes siguientes respaldan aspectos concretos sobre agentes, contexto, acceso a datos y automatización; no certifican la seguridad de un proyecto particular."}, {"type": "h", "text": "1 Ingeniería del contexto"}, {"type": "p", "text": "Anthropic · Effective context engineering for AI agents. Contexto pertinente, notas y continuidad de tareas.\nhttps://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents"}, {"type": "h", "text": "2 Límites del entorno del agente"}, {"type": "p", "text": "Anthropic · Beyond permission prompts making Claude Code more secure and autonomous. Aislamiento de archivos y red y riesgos de inyección de instrucciones.\nhttps://www.anthropic.com/engineering/claude-code-sandboxing"}, {"type": "h", "text": "3 Revisión humana y límites de agentes"}, {"type": "p", "text": "GitHub Docs · Application card GitHub Copilot Agents. Verificación de resultados y revisión con IA como complemento.\nhttps://docs.github.com/en/copilot/responsible-use/agents"}, {"type": "h", "text": "4 Claves y acceso a Supabase"}, {"type": "p", "text": "Supabase Docs · API keys. Diferencia entre claves publicables, secretas y acceso mediante políticas.\nhttps://supabase.com/docs/guides/getting-started/api-keys"}, {"type": "h", "text": "5 Integración continua"}, {"type": "p", "text": "GitHub Docs · Understanding GitHub Actions. Automatización de compilación y pruebas.\nhttps://docs.github.com/en/actions/get-started/understand-github-actions"}, {"type": "h", "text": "6 Migraciones de datos"}, {"type": "p", "text": "Supabase Docs · Deploy database migrations. Registro y aplicación de cambios de esquema.\nhttps://supabase.com/docs/guides/deployment/database-migrations"}, {"type": "p", "text": "Fuentes consultadas el 30 de octubre de 2026. Verifica versiones y condiciones de los servicios antes de aplicar comandos o configuraciones. Para productos con riesgos altos o requisitos sectoriales, agrega revisión especializada proporcional a su contexto."}], "number": 23, "description": "Esta edición reorganiza y amplía el material inicial con criterios editoriales de desarrollo de producto e ingeniería. Las plantillas son ejemplos adaptables. Las fuentes siguientes respaldan aspectos concretos sobre agentes, contexto, acceso a datos y automatización; no certifican la seguridad de un proyecto particular."}];
